<div class="calendar-toolbar"><a class="icon-button bordered" aria-label="Semana anterior" href="<?= e(url('calendar',['week'=>$start->modify('-7 days')->format('Y-m-d'),'room'=>$roomId])) ?>"><?= icon('chevron-left') ?></a><strong>Semana <?= $start->format('d/m') ?>–<?= $start->modify('+4 days')->format('d/m/Y') ?></strong><a class="icon-button bordered" aria-label="Próxima semana" href="<?= e(url('calendar',['week'=>$start->modify('+7 days')->format('Y-m-d'),'room'=>$roomId])) ?>"><?= icon('chevron-right') ?></a><form method="get"><input type="hidden" name="page" value="calendar"><input type="hidden" name="week" value="<?= $start->format('Y-m-d') ?>"><select name="room" aria-label="Filtrar calendário por sala" data-autosubmit><option value="0">Todas as salas</option><?php foreach($rooms as $room): ?><option value="<?= $room['id'] ?>" <?= $roomId===(int)$room['id']?'selected':'' ?>><?= e($room['name']) ?></option><?php endforeach; ?></select><noscript><button>Filtrar</button></noscript></form><a class="text-link" href="<?= e(url('calendar')) ?>">Hoje</a></div>
<section class="card table-scroll"><table class="calendar-table"><thead><tr><th>Hora</th><?php foreach(['Seg','Ter','Qua','Qui','Sex'] as $offset=>$day): $date=$start->modify('+'.$offset.' days'); ?><th class="<?= $date->format('Y-m-d')===date('Y-m-d')?'today':'' ?>"><?= $day ?><small><?= $date->format('d/m') ?></small></th><?php endforeach; ?></tr></thead><tbody><?php for($h=7;$h<18;$h++): $hour=sprintf('%02d:00',$h); ?><tr><th><?= $hour ?></th><?php for($d=0;$d<5;$d++): $date=$start->modify('+'.$d.' days')->format('Y-m-d');$items=array_filter($rows,fn($b)=>$b['date']===$date&&substr($b['start_time'],0,5)<=$hour&&substr($b['end_time'],0,5)>$hour&&in_array($b['status'],['Confirmado','Pendente'],true)); ?><td><?php if(!$items): ?><div class="calendar-free"><span class="sr-only">Livre</span></div><?php else:foreach($items as $b): ?><a class="calendar-event <?= $b['status']==='Pendente'?'pending':'' ?>" href="<?= e(url('approvals',['tab'=>'all'])) ?>" title="<?= e($b['purpose'].' · '.$b['status']) ?>"><strong><?= e($b['teacher']) ?></strong><span><?= e($b['room_name']) ?></span></a><?php endforeach;endif; ?></td><?php endfor; ?></tr><?php endfor; ?></tbody></table></section><div class="calendar-legend"><span><b class="legend-free"></b>Livre</span><span><b></b>Confirmado</span><span><b class="legend-pending"></b>Pendente</span></div>
